type WorldStateHandle = Record<string, string>;

const INITIAL_STATE: WorldStateHandle = {
  Fen: "nim",
};

export const protocol: WorldProtocol = {
  reset(): WorldStateHandle {
    return { ...INITIAL_STATE };
  },

  applyOperation(
    state: WorldStateHandle,
    operationDisplayName: string
  ):
    | { success: true; newState: WorldStateHandle }
    | { success: false; error: string } {
    if (operationDisplayName !== "resetFen") {
      return {
        success: false,
        error: `Unknown operation: ${operationDisplayName}`,
      };
    }

    if (state.Fen !== "pex") {
      return {
        success: false,
        error: 'resetFen requires Fen to be in state "pex"',
      };
    }

    return {
      success: true,
      newState: {
        ...state,
        Fen: "nim",
      },
    };
  },

  getEntityState(state: WorldStateHandle, entityDisplayName: string): string {
    return state[entityDisplayName] ?? "unknown";
  },

  toAbstractSnapshot(state: WorldStateHandle): Record<string, string> {
    return { ...state };
  },
};"}],"workingNote":"Fen の初期状態を nim とし、pex のときだけ resetFen を適用して nim へ遷移させます。状態は不変更新し、reset・スナップショット・エンティティ取得の公開シグネチャを維持しています。"}

